<script setup>
import { computed, ref, watch } from 'vue'
import { Plus, CalendarDays, Target, Play, Check, X, Trash2, Pencil, MessageSquare, ArrowRight } from 'lucide-vue-next'
import { useWorkboard } from '../stores/workboard'
import { api } from '../api'
const props = defineProps({ mode: String })
const emit = defineEmits(['show-sprint'])
const store = useWorkboard()
const selected = ref(null), dialog = ref(null), editing = ref(null)
const title = ref(''), goal = ref(''), start = ref(''), end = ref('')
const content = ref(''), category = ref('positive'), noteId = ref(null)
const history=ref([]),historyTitle=ref('')
async function viewHistory(s) {await store.run(async()=>{history.value=await api(`sprints/${s.id}/history/`);historyTitle.value=s.title;dialog.value='history'})}
const statuses = { planned: 'Planejada', active: 'Em andamento', completed: 'Encerrada' }
const categories = [{ id:'positive', title:'O que foi bem', hint:'Conquistas e práticas para manter.' }, { id:'improve', title:'O que pode melhorar', hint:'Dificuldades e aprendizados do ciclo.' }, { id:'action', title:'Próximas ações', hint:'Melhorias concretas para o próximo ciclo.' }]
const sprints = computed(() => store.board?.sprints ?? [])
const available = computed(() => sprints.value.filter(s => s.status !== 'planned'))
const sprint = computed(() => sprints.value.find(s => s.id === selected.value))
const tasks = computed(() => store.board?.columns.flatMap(c => c.tasks.filter(t=>!t.archived).map(t => ({...t, columnKind:c.kind}))) ?? [])
watch(available, list => { if (!list.some(s => s.id === selected.value)) selected.value = list.find(s => s.status === 'active')?.id ?? list[0]?.id ?? null }, { immediate:true })
function stats(s) {
  if (s.status === 'completed') return { total:s.total_at_close, done:s.completed_at_close }
  return {total:s.task_total,done:s.task_completed}
}
function date(value) { return new Date(`${value}T12:00:00`).toLocaleDateString('pt-BR') }
function openSprint(s) { editing.value=s?.id ?? null; title.value=s?.title ?? ''; goal.value=s?.goal ?? ''; start.value=s?.start_date ?? ''; end.value=s?.end_date ?? ''; dialog.value='sprint' }
async function saveSprint() { await store.run(async () => { await store.mutate(`sprints/${editing.value ? `${editing.value}/` : ''}`, editing.value?'PATCH':'POST', {board:store.selected,title:title.value,goal:goal.value,start_date:start.value,end_date:end.value}); dialog.value=null }) }
async function begin(s) { await store.run(() => store.mutate(`sprints/${s.id}/start/`,'POST',{})) }
async function complete() { await store.run(async () => { await store.mutate(`sprints/${editing.value}/complete/`,'POST',{}); selected.value=editing.value; dialog.value=null }) }
async function deleteSprint() { await store.run(async () => { await store.mutate(`sprints/${editing.value}/`,'DELETE'); dialog.value=null }) }
function openNote(cat, note) { category.value=cat; noteId.value=note?.id ?? null; content.value=note?.content ?? ''; dialog.value='note' }
async function saveNote() { await store.run(async () => { await store.mutate(`retro-notes/${noteId.value ? `${noteId.value}/` : ''}`,noteId.value?'PATCH':'POST',{sprint:selected.value,category:category.value,content:content.value}); dialog.value=null }) }
async function deleteNote() { if(!window.confirm('Excluir esta nota da retrospectiva?')) return; const previous={sprint:selected.value,category:category.value,content:content.value,done:sprint.value.notes.find(n=>n.id===noteId.value)?.done ?? false}; await store.run(async () => { await store.mutate(`retro-notes/${noteId.value}/`,'DELETE');store.offerUndo('Nota excluída.',()=>store.mutate('retro-notes/','POST',previous)); dialog.value=null }) }
async function toggle(note) { await store.run(() => store.mutate(`retro-notes/${note.id}/`,'PATCH',{done:!note.done})) }
</script>

<template>
  <section v-if="mode==='sprints'" class="sprint-workspace">
    <div class="section-heading"><div><span class="eyebrow">PLANEJE O PRÓXIMO CICLO</span><h2>Sprints do projeto</h2><p>Um objetivo claro, um período definido e espaço para entregar.</p></div><button v-if="store.canWrite" class="primary" :disabled="store.busy" @click="openSprint()"><Plus :size="17"/> Nova sprint</button></div>
    <div v-if="!sprints.length" class="feature-empty"><CalendarDays :size="38"/><h3>Comece com um objetivo.</h3><p>Crie uma sprint e vincule as tarefas pelo editor dos cartões.</p><button v-if="store.canWrite" class="primary" @click="openSprint()">Criar primeira sprint</button></div>
    <div v-else class="sprint-grid"><article v-for="s in sprints" :key="s.id" class="sprint-card"><div class="sprint-card-top"><span class="sprint-status" :class="s.status">{{statuses[s.status]}}</span><button v-if="s.status==='planned' && store.canWrite" :aria-label="`Editar ${s.title}`" :disabled="store.busy" @click="openSprint(s)"><Pencil :size="16"/></button></div><h3>{{s.title}}</h3><p class="sprint-goal"><Target :size="16"/>{{s.goal || 'Sem objetivo definido.'}}</p><div class="sprint-dates"><CalendarDays :size="15"/>{{date(s.start_date)}} — {{date(s.end_date)}}</div><div class="sprint-progress-label"><span>{{stats(s).done}} de {{stats(s).total}} tarefas concluídas</span><strong>{{stats(s).total ? Math.round(stats(s).done/stats(s).total*100) : 0}}%</strong></div><progress :value="stats(s).done" :max="stats(s).total || 1"></progress><p v-if="s.status==='completed'" class="sprint-history">Resultado registrado no encerramento. Pendências retornaram ao backlog.</p><div class="sprint-card-actions"><button class="secondary" @click="emit('show-sprint',s.id)">Ver tarefas <ArrowRight :size="15"/></button><button v-if="s.status==='planned' && store.canWrite" class="primary" :disabled="store.busy || sprints.some(item => item.status==='active')" @click="begin(s)"><Play :size="14"/> Iniciar sprint</button><button v-if="s.status==='active' && store.canWrite" class="primary" :disabled="store.busy" @click="editing=s.id;dialog='complete'"><Check :size="15"/> Encerrar sprint</button></div><button class="text-button" :aria-label="`Histórico de ${s.title}`" @click="viewHistory(s)">Histórico da sprint</button></article></div>
    <p class="feature-help">Uma sprint em andamento por quadro. As datas orientam o planejamento; início e encerramento são manuais.</p>
  </section>
  <section v-else class="retro-workspace"><div class="section-heading"><div><span class="eyebrow">APRENDER PARA EVOLUIR</span><h2>Retrospectiva</h2><p>Registre o que funcionou e transforme aprendizados em ações.</p></div><label v-if="available.length" class="retro-selector">Sprint<select v-model="selected" aria-label="Sprint da retrospectiva"><option v-for="s in available" :key="s.id" :value="s.id">{{s.title}} · {{statuses[s.status]}}</option></select></label></div><div v-if="!sprint" class="feature-empty"><MessageSquare :size="38"/><h3>Cada ciclo traz um aprendizado.</h3><p>Inicie uma sprint na aba Sprints para abrir sua retrospectiva.</p></div><template v-else><div class="retro-summary"><div><strong>{{sprint.title}}</strong><p>{{sprint.goal || 'Reflita sobre o trabalho deste ciclo.'}}</p></div><span class="sprint-status" :class="sprint.status">{{statuses[sprint.status]}}</span><span>{{stats(sprint).done}} / {{stats(sprint).total}} tarefas concluídas</span></div><div class="retro-grid"><section v-for="cat in categories" :key="cat.id" class="retro-column" :class="cat.id"><div class="retro-column-heading"><h3>{{cat.title}}</h3><span class="count">{{sprint.notes.filter(n => n.category===cat.id).length}}</span></div><p>{{cat.hint}}</p><article v-for="note in sprint.notes.filter(n => n.category===cat.id)" :key="note.id" class="retro-note" :class="{done:note.done}"><p>{{note.content}}</p><div class="retro-note-actions"><button v-if="cat.id==='action' && store.canWrite" :disabled="store.busy" @click="toggle(note)"><Check :size="14"/>{{note.done?'Reabrir ação':'Concluir ação'}}</button><button v-if="store.canWrite" :aria-label="`Editar nota: ${note.content}`" :disabled="store.busy" @click="openNote(cat.id,note)"><Pencil :size="14"/></button></div></article><button v-if="store.canWrite" class="add-task" :disabled="store.busy" @click="openNote(cat.id)"><Plus :size="16"/>{{cat.id==='action'?'Adicionar ação':'Adicionar nota'}}</button></section></div></template></section>
  <div v-if="dialog" class="modal-backdrop" @click.self="!store.busy && (dialog=null)" @keydown.esc="!store.busy && (dialog=null)"><section v-dialog class="modal" role="dialog" aria-modal="true" aria-labelledby="feature-dialog-title"><div class="modal-heading"><h2 id="feature-dialog-title">{{dialog==='history'?'Histórico da sprint':dialog==='sprint'?(editing?'Editar sprint':'Nova sprint'):dialog==='complete'?'Encerrar sprint':noteId?'Editar nota':'Nova nota'}}</h2><button aria-label="Fechar" :disabled="store.busy" @click="dialog=null"><X :size="20"/></button></div><section v-if="dialog==='history'" class="sprint-history-list"><h3>{{historyTitle}}</h3><p v-if="!history.length">Nenhuma tarefa participou desta sprint.</p><article v-for="entry in history" :key="entry.id" class="history-entry"><strong>#{{entry.task_key}} · {{entry.snapshot.title}}</strong><p>{{entry.snapshot.description}}</p><span class="sprint-status">{{entry.snapshot.deleted?'Excluída no registro':entry.snapshot.archived?'Arquivada no registro':entry.snapshot.completed?'Concluída':'Pendente'}} · {{entry.snapshot.column}}</span><p>{{entry.snapshot.assignee || 'Sem responsável'}} · {{entry.removed_at?'Retirada antes do encerramento':'Participante do ciclo'}}</p><small v-if="entry.snapshot.legacy">Registro inicial importado; dados anteriores não estavam disponíveis.</small></article></section><form v-else-if="dialog==='sprint'" @submit.prevent="saveSprint"><label>Nome da sprint<input v-model="title" required maxlength="120" placeholder="Sprint 01 — Fundação"></label><label>Objetivo<textarea v-model="goal" maxlength="2000" rows="3" placeholder="Qual resultado queremos alcançar?"></textarea></label><div class="form-row"><label>Data inicial<input v-model="start" type="date" required></label><label>Data final<input v-model="end" type="date" :min="start" required></label></div><p v-if="store.error" class="error" role="alert">{{store.error}}</p><div class="modal-actions"><button v-if="editing" type="button" class="danger" :disabled="store.busy" @click="dialog='delete'"><Trash2 :size="16"/> Excluir sprint</button><button class="primary" :disabled="store.busy">{{store.busy?'Salvando…':'Salvar sprint'}}</button></div></form><form v-else-if="dialog==='note'" @submit.prevent="saveNote"><label>{{categories.find(c => c.id===category)?.title}}<textarea v-model="content" required maxlength="2000" rows="5" placeholder="Registre seu aprendizado..."></textarea></label><p v-if="store.error" class="error" role="alert">{{store.error}}</p><div class="modal-actions"><button v-if="noteId" type="button" class="danger" :disabled="store.busy" @click="deleteNote"><Trash2 :size="16"/> Excluir nota</button><button class="primary" :disabled="store.busy">Salvar nota</button></div></form><template v-else><p>{{dialog==='complete'?'O resultado será registrado e as tarefas que não estão em Concluído voltarão ao backlog, sem serem excluídas. A sprint encerrada não poderá ser reaberta; sua retrospectiva continuará disponível.':'A sprint planejada será excluída. As tarefas serão preservadas no backlog.'}}</p><p v-if="store.error" class="error" role="alert">{{store.error}}</p><div class="modal-actions"><button class="secondary" :disabled="store.busy" @click="dialog=null">Cancelar</button><button class="primary" :disabled="store.busy" @click="dialog==='complete'?complete():deleteSprint()">{{dialog==='complete'?'Confirmar encerramento':'Confirmar exclusão'}}</button></div></template></section></div>
</template>
